interface DirectDelivery {
  readonly reasons: string[];
  readonly next: string[];
  readonly artifacts: OutcomeReadinessArtifact[];
  readonly delivery: OutcomeReadinessDelivery | null;
}

async function directDelivery(
  deps: WorkRuntimeDeps,
  status: ReturnType<WorkRuntimeDeps["controller"]["status"]>,
  requested: string | null,
): Promise<DirectDelivery | null> {
  const { controller, deliveryPulse } = deps;
  const direct = status.directOutcome;
  const head = direct?.repositoryHead;
  const repository = controller.effects.git.repository;
  if (
    deliveryPulse === undefined || repository === undefined || !direct || !head ||
    (direct.relation !== "IN_SYNC" && direct.relation !== "DIRECT_AHEAD") ||
    status.attempts.some((attempt) => attempt.orphaned === true)
  ) return null;

  const plannedIds = new Set(controller.work.project().tasks.map((task) => task.task_id));
  const retired = status.tasks.filter((task) => task.state === "STALE" && !plannedIds.has(task.task_id));
  const retiredMode = retired.length > 0 && (requested === null || retired.some((task) => task.task_id === requested));
  const tasklessMode = requested === null && (status.tasks?.length ?? 0) === 0;
  if (!retiredMode && !tasklessMode) return null;

  const pulse = await deliveryPulse.pulse().catch(() => null);
  if (
    pulse === null || pulse.basis.projectRevision !== status.revision || pulse.basis.headCommit !== status.headCommit ||
    pulse.episode.readiness.deliveryBlockers.length > 0 || pulse.episode.readiness.failedOrBlockedTasks.length > 0 ||
    pulse.execution.jobs.some((job) => job.phase === "QUEUED" || job.phase === "RUNNING")
  ) return null;
  const recordedDeliver = pulse.episode.current && pulse.episode.state === "DELIVERED";

  // "No task" is not by itself a reason to deliver: the repository must have moved beyond the basis,
  // unless this episode already has a current conclusion that the next session should reuse.
  if (tasklessMode && direct.relation !== "DIRECT_AHEAD" && !recordedDeliver) return null;

  const git = gitTextRunner(repository);
  const artifacts = new Set<string>();
  if (retiredMode) {
    for (const task of retired) {
      const envelope = controller.taskEnvelopeOrNull(task.task_id);
      if (envelope === null) return null;
      for (const path of envelope.required_artifacts) artifacts.add(path);
    }
    if (artifacts.size === 0) return null;
  } else {
    // A taskless direct commit is a reviewable result only if Git can name what it changed. This is
    // also the missing half after a guard refresh: the recorded conclusion can cover files from an
    // older commit, while the direct advance's CHANGED paths are what the next session needs. The
    // paths are candidates for the episode's artifacts; this is not an acceptance of their content.
    const changed = changedBlobPaths(git, direct.projectHead, head);
    if (changed === null) return null;
    for (const path of changed) artifacts.add(path);
    if (!recordedDeliver && artifacts.size === 0) return null;
    if (recordedDeliver && artifacts.size === 0) {
      // IN_SYNC (or a no-op advance): reuse the recorded conclusion's own committed artifacts so a
      // next session still receives the delivery record instead of an empty list.
      for (const artifact of pulse.episode.conclusion?.check.artifacts ?? []) {
        if (artifact.committed && artifact.path !== "") artifacts.add(artifact.path);
      }
    }
  }

  // Re-observe Git after the asynchronous episode read. An unobservable worktree cannot prove a clean basis.
  const basis = observeCanonicalBasis(repository);
  if (basis?.head !== head || basis.uncommittedPaths?.length !== 0) return null;
  const paths = [...artifacts];
  const states: OutcomeReadinessArtifact[] = [];
  try {
    for (const path of paths) {
      const present = statSync(join(repository, path), { throwIfNoEntry: false })?.isFile() === true;
      const committed = git(["cat-file", "-t", `${head}:${path}`])?.trim() === "blob";
      if (!recordedDeliver && (!present || !committed)) return null;
      states.push(Object.freeze({ path, present, committed }));
    }
  } catch {
    return null;
  }

  const conclusion = recordedDeliver ? pulse.episode.conclusion : null;
  const delivery: OutcomeReadinessDelivery | null = conclusion === null
    ? null
    : Object.freeze({
        conclusionId: conclusion.conclusionId,
        intent: "DELIVER" as const,
        recordedAt: conclusion.recordedAt,
        basisHeadCommit: conclusion.basis.headCommit,
        artifacts: Object.freeze(states),
      });

  const changedSummary = tasklessMode && paths.length > 0 ? ` The direct commit changed ${paths.join(", ")}.` : "";
  const reason = tasklessMode
    ? direct.relation === "DIRECT_AHEAD"
      ? `the repository has a direct commit at HEAD ${head}, ahead of the canonical head ${direct.projectHead}; no formal Work is open.${changedSummary}`
      : `the repository and canonical head agree at ${head}; no formal Work is open.${changedSummary}`
    : `the retired plan's declared artifacts (${paths.join(", ")}) are committed at repository HEAD ${head}`;
  if (recordedDeliver) {
    const named = paths.length === 0 ? "" : ` The recorded DELIVER conclusion names ${paths.join(", ")} at ${head}.`;
    return {
      reasons: [reason, "this episode has a current recorded DELIVER conclusion", ...(named === "" ? [] : [named.trim()])],
      next: ["reply using the recorded conclusion"],
      artifacts: states,
      delivery,
    };
  }
  return {
    reasons: [reason, "the episode has no mechanical delivery blockers; decide whether the committed result satisfies the user's goal"],
    next: tasklessMode
      ? [paths.length > 0
          ? `if the committed result satisfies the goal, call palimpsest_work action=conclude intent=DELIVER with your statement and artifacts ${JSON.stringify(paths)}`
          : "if the committed result satisfies the goal, call palimpsest_work action=conclude intent=DELIVER with your statement"]
      : ["if the committed artifacts satisfy the goal, call palimpsest_work action=conclude intent=DELIVER with your statement and the artifact paths"],
    artifacts: states,
    delivery,
  };
}

